// ===================== PASTE YOUR KEYS HERE =====================
// Fill these in inside n8n. Do NOT paste them into a copy of this file that
// gets committed anywhere — this workflow lives in a public repo, and a key
// in a JSON file is a key on the internet.
//
// G2 is the one that catches people out: its API wants
//   Authorization: Token token=<key>
// not Bearer. Put ONLY the raw key here; the header node adds the
// "Token token=" prefix itself.
const KEYS = {
  g2:         '',   // data.g2.com token — my.g2.com/developers/<your-slug>
  linkfinder: '',   // LinkFinder AI API key
  instantly:  ''    // Instantly API key
};

return [{ json: {
  keys: KEYS,
  // Set false if you have no data.g2.com API token. The run then sources
  // from Hacker News alone, which needs no credential at all.
  //
  // This is a real distinction worth checking before you flip it on: a G2
  // *account*, and even a working G2 MCP/OAuth connection, is not the same
  // thing as an API token for data.g2.com. If you do not have that token,
  // leaving this true fails the whole run — a missing credential is a
  // node-level error in n8n and neverError does not catch it, because
  // neverError only suppresses HTTP error *responses*.
  useG2: true,

  campaignId: 'df17f3eb-368d-415f-99ab-b6a7325dad3c',
  batchSize: 10,          // enrichment attempts per hour
  topUpBelow: 40,         // refill the queue when it drops under this
  maxAttempts: 3,         // then move on; not every company is findable
  g2Categories: [
    'ai-sales-roleplay-tools','ai-proposal-generator-tools','event-lead-capture',
    'ai-interview-agent','ai-documentation-generators','site-search-software',
    'ai-sre-tools','website-privacy-auditing-tools','ai-agent-observability',
    'semantic-layer-tools','virtual-recording-studio','low-code-mobile-app-builder'
  ],
  g2MinReviews: 10, g2MaxReviews: 250,
  excludeDomains: [
    'linkfinderai.com','clay.com','warmly.ai','6sense.com','apollo.io',
    'zoominfo.com','lusha.com','cognism.com','hunter.io','snov.io',
    'rocketreach.co','seamless.ai','uplead.com','findymail.com','dropcontact.com',
    'kaspr.io','surfe.com','prospeo.io','anymailfinder.com','tryprofound.com',
    'peec.ai','otterly.ai','athenahq.ai','scrunchai.com','goodie.ai','brandlight.ai'
  ],
  excludeHosts: [
    'producthunt.com','github.com','gitlab.com','medium.com','substack.com',
    'notion.so','notion.site','youtube.com','twitter.com','x.com',
    'news.ycombinator.com','reddit.com','linkedin.com','vercel.app',
    'netlify.app','herokuapp.com','pages.dev','webflow.io'
  ]
} }];

// Decide, once per run, whether there is anything worth doing.
//
// Two independent reasons to stop early, and stopping is not a failure:
//   - no room in Instantly  -> enriching would burn credits on leads that
//                              cannot be uploaded
//   - queue still full      -> no need to hit the sources at all
//
// The queue lives in n8n's own workflow storage. No database to set up, it
// survives restarts, and it is what turns an unreliable provider into a
// reliable pipeline: a domain that fails this hour is simply still there
// next hour.
const cfg = $('Config').first().json;

// Catch an unset key here rather than as a confusing 401 six nodes later.
const k = cfg.keys || {};
const missing = [];
if (!k.instantly)  missing.push('instantly');
if (!k.linkfinder) missing.push('linkfinder');
if (cfg.useG2 && !k.g2) missing.push('g2 (or set useG2:false)');
if (missing.length) {
  throw new Error('Open the Config node and fill in: ' + missing.join(', ') +
    '. Keys go in the KEYS object at the top.');
}
const plan = $input.first().json;
const sub = plan?.subscriptions?.outreach || plan || {};
const limit = sub.total_lead_limit, used = sub.current_lead_count;

let room;
if (limit == null || used == null) {
  room = cfg.batchSize;   // unreadable: proceed cautiously, one batch
} else {
  room = limit - used;
}

const store = $getWorkflowStaticData('global');
store.queue = store.queue || [];
store.done  = store.done  || {};
store.stats = store.stats || { pushed: 0, dead: 0, retries: 0, runs: 0 };
store.stats.runs++;

if (room <= 0) {
  return [{ json: { ...cfg, halt: true,
    reason: `Instantly is ${-room} leads over its cap (${used}/${limit}). ` +
            `Nothing enriched — that would spend credits on leads it will refuse. ` +
            `Queue is holding ${store.queue.length} domains and loses nothing by waiting.` } }];
}

return [{ json: { ...cfg,
  halt: false,
  room,
  queueLength: store.queue.length,
  needsTopUp: store.queue.length < cfg.topUpBelow
} }];

const cfg = $input.first().json;
// No G2 token -> emit no items, so the G2 request node never executes and
// never asks for a credential that does not exist. Hacker News carries the
// run on its own.
if (!cfg.useG2) return [];
return cfg.g2Categories.map(slug => ({ json: { ...cfg, slug } }));

// Both sources -> the queue. Anything already queued, already sent, or
// already written off is dropped here, so the queue never grows duplicates
// and a domain is never paid for twice.
const cfg = $('Plan this run').first().json;
const store = $getWorkflowStaticData('global');
const seen = new Set([...store.queue.map(q => q.domain), ...Object.keys(store.done)]);

const bad = d =>
  cfg.excludeDomains.includes(d) ||
  cfg.excludeHosts.some(h => d === h || d.endsWith('.' + h));

let added = 0;

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;

  // --- G2 -------------------------------------------------------------
  if (body?.included) {
    const category = body?.data?.attributes?.name || 'software';
    const products = body.included
      .filter(i => i.type === 'products' && i.attributes?.domain)
      .map(i => ({
        domain: String(i.attributes.domain).trim().toLowerCase().replace(/^www\./, ''),
        company: i.attributes.name || '',
        reviews: i.attributes.review_count || 0
      }));
    if (products.length && Math.min(...products.map(p => p.reviews)) <= cfg.g2MaxReviews) {
      for (const p of products) {
        if (seen.has(p.domain) || bad(p.domain)) continue;
        if (p.reviews < cfg.g2MinReviews || p.reviews > cfg.g2MaxReviews) continue;
        seen.add(p.domain); added++;
        store.queue.push({ domain: p.domain, company: p.company, category,
          signalValue: p.reviews, source: 'g2', attempts: 0 });
      }
    }
  }

  // --- Hacker News ----------------------------------------------------
  if (Array.isArray(body?.hits)) {
    for (const h of body.hits) {
      if ((h.points || 0) < 20) continue;
      let host = '';
      try { host = new URL(h.url || '').hostname.toLowerCase().replace(/^www\./, ''); } catch { continue; }
      if (!host || seen.has(host) || bad(host)) continue;
      const company = (String(h.title || '').replace(/^show hn:?\s*/i, '')
        .split(/[\u2013\u2014\-:|,]/)[0] || host).trim();
      seen.add(host); added++;
      store.queue.push({ domain: host, company: company || host, category: 'software',
        signalValue: h.points || 0, source: 'hackernews', attempts: 0 });
    }
  }
}

return [{ json: { ...cfg, added, queueLength: store.queue.length } }];

// Take this hour's batch off the queue.
//
// Oldest first, and anything that has burned through maxAttempts is written
// off here rather than retried forever. A domain with no reachable decision
// maker is not going to grow one.
const cfg = $('Plan this run').first().json;
const store = $getWorkflowStaticData('global');
const take = Math.min(cfg.batchSize, cfg.room, store.queue.length);

const batch = [];
while (batch.length < take && store.queue.length) {
  const row = store.queue.shift();
  if (!row) break;
  if ((row.attempts || 0) >= cfg.maxAttempts) {
    store.done[row.domain] = 'gave_up';
    store.stats.dead++;
    continue;
  }
  batch.push({ json: { ...row, campaignId: cfg.campaignId } });
}

if (!batch.length) {
  return [{ json: { idle: true, queueLength: store.queue.length,
    note: 'nothing to enrich this hour' } }];
}
return batch;

// Sort the answer into: usable, retry later, or written off.
//
// This endpoint answers HTTP 200 / "success" even when its upstream is
// down, putting a status message where a person should be:
//   {"personId": null, "name": "We are on maintenance. Check back in 48hrs"}
// Measured across ~20 live calls: roughly HALF. So the sentinel is not an
// error to report, it is a "not now" to reschedule.
//
// ORDER MATTERS. Look for a real person FIRST. The actor also injects a
// chatty banner row alongside genuine results, so checking sentinels first
// throws away a good lead and pays to look it up again.
const OUTAGE = ['maintenance','check back in','we improve the actor','contact us if you are having'];
const store = $getWorkflowStaticData('global');
const row = $('One at a time').first().json;

const body = $input.first().json;
const payload = body?.body ?? body;
let rows = payload?.result ?? payload?.employees ?? payload;
while (rows && !Array.isArray(rows) && rows.result) rows = rows.result;
if (!Array.isArray(rows)) rows = [];

const person = rows.find(r => r && (r.personId || r.person_id) &&
  r.email && String(r.email).includes('@') && r.name);

if (person) {
  const parts = String(person.name).trim().split(/\s+/);
  return [{ json: { ...row, status: 'ok', email: person.email.trim(),
    firstName: parts[0], lastName: parts.slice(1).join(' '),
    title: person.jobTitle || person.job_title || '' } }];
}

const sentinel = rows.find(r => r && !r.personId && !r.person_id &&
  OUTAGE.some(m => String(r.name || '').toLowerCase().includes(m)));

if (sentinel) {
  // Not this company's fault. Back on the queue, try again next hour.
  store.queue.push({ ...row, attempts: (row.attempts || 0) + 1 });
  store.stats.retries++;
  return [{ json: { ...row, status: 'requeued' } }];
}

// A real, empty answer. Nobody reachable here; stop paying to ask.
store.done[row.domain] = 'no_person';
store.stats.dead++;
return [{ json: { ...row, status: 'no_person' } }];

// Record the outcome of the push.
//
// A failed upload is deliberately put BACK on the queue: we already paid to
// enrich this lead, so it is the single most valuable thing to retry. A
// successful one is marked done so it is never sourced or enriched again.
const store = $getWorkflowStaticData('global');
const row = $('Usable?').first().json;
const res = $input.first().json;
const code = res?.statusCode ?? res?.status ?? 200;
const ok = !(code >= 400) && !res?.error;

if (ok) {
  store.done[row.domain] = row.email;
  store.stats.pushed++;
  return [{ json: { domain: row.domain, email: row.email, status: 'pushed' } }];
}

store.queue.push({ ...row, attempts: (row.attempts || 0) + 1 });
return [{ json: { domain: row.domain, status: 'push_failed_requeued',
  detail: JSON.stringify(res).slice(0, 200) } }];

// End-of-run summary. Read this in n8n's execution list to see whether the
// pipeline is healthy without opening anything.
const store = $getWorkflowStaticData('global');
const s = store.stats || {};
return [{ json: {
  queueRemaining: store.queue.length,
  finished: Object.keys(store.done).length,
  pushedTotal: s.pushed || 0,
  wroteOff: s.dead || 0,
  retriesSoFar: s.retries || 0,
  runs: s.runs || 0
} }];
